@triton.jit
def _strided_kernel(
    ptr,
    n_elements,
    m0,
    m1,
    m2,
    m3,
    m4,
    m5,
    m6,
    m7,
    c0,
    c1,
    c2,
    c3,
    c4,
    c5,
    c6,
    c7,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    mask = offs < n_elements
    rem = offs
    off = offs - offs
    if RANK > 0:
        i = rem % m0
        rem = rem // m0
        off += i * c0
    if RANK > 1:
        i = rem % m1
        rem = rem // m1
        off += i * c1
    if RANK > 2:
        i = rem % m2
        rem = rem // m2
        off += i * c2
    if RANK > 3:
        i = rem % m3
        rem = rem // m3
        off += i * c3
    if RANK > 4:
        i = rem % m4
        rem = rem // m4
        off += i * c4
    if RANK > 5:
        i = rem % m5
        rem = rem // m5
        off += i * c5
    if RANK > 6:
        i = rem % m6
        rem = rem // m6
        off += i * c6
    if RANK > 7:
        i = rem % m7
        rem = rem // m7
        off += i * c7
