# entry point
# ---------------------------------------------------------------------------


def foreach_log1p_(self):
    if not isinstance(self, (list, tuple)):
        raise TypeError("argument 'self' must be tuple of Tensors")
    if len(self) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")
    if len(self) == 1:
        t = self[0]
        if not isinstance(t, torch.Tensor):
            raise TypeError("argument 'self' must be tuple of Tensors")
        if t.dtype not in _FLOAT_DTYPES:
            raise RuntimeError(
                "result type Float can't be cast to the desired output type "
                + str(t.dtype).replace("torch.", "").capitalize()
            )
        n = t.numel()
        if n == 0:
            return None
        if _is_flat(t):
            _launch_flat1(t, n)
        else:
            _apply_strided(t)
        return None

    groups = None
    strided = None
    for t in self:
        if not isinstance(t, torch.Tensor):
            raise TypeError("argument 'self' must be tuple of Tensors")
        if t.dtype not in _FLOAT_DTYPES:
            raise RuntimeError(
                "result type Float can't be cast to the desired output type "
                + str(t.dtype).replace("torch.", "").capitalize()
            )
        n = t.numel()
        if n == 0:
            continue
        if _is_flat(t):
            if groups is None:
                groups = {}
            key = (t.get_device(), t.dtype, n)
            bucket = groups.get(key)
            if bucket is None:
                groups[key] = [t]
            else:
                bucket.append(t)
        else:
            if strided is None:
                strided = []
            strided.append(t)

    if groups is not None:
        for key, ts in groups.items():
            n = key[2]
            m = len(ts)
            if m == 1:
                _launch_flat1(ts[0], n)
            elif _separated(ts, n):
                for i in range(0, m, _MAX_M):
                    _launch_flat(ts[i : i + _MAX_M], n)
            else:
                for t in ts:
                    _launch_flat1(t, n)

    if strided is not None:
        for t in strided:
            _apply_strided(t)
    return None
